cat > /tmp/parse_binlog.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("/tmp/sv-88e3ad8e64724c01bb2753940edfdf4d/build.binlog");
Console.WriteLine($"Build Succeeded: {build.Succeeded}");
Console.WriteLine();

// Find all errors
var errors = new List<(string file, int line, string code, string msg, string project)>();
build.VisitAllChildren<Error>(e => {
    errors.Add((e.File ?? "", e.LineNumber, e.Code ?? "", e.Message ?? "", e.ProjectFile ?? ""));
});

Console.WriteLine($"Total errors: {errors.Count}");
Console.WriteLine();
foreach (var e in errors) {
    Console.WriteLine($"[{e.project}]");
    Console.WriteLine($"  {e.file}({e.line}): error {e.code}: {e.msg}");
    Console.WriteLine();
}

// Find all warnings
var warnings = new List<(string file, int line, string code, string msg, string project)>();
build.VisitAllChildren<Warning>(w => {
    warnings.Add((w.File ?? "", w.LineNumber, w.Code ?? "", w.Message ?? "", w.ProjectFile ?? ""));
});

if (warnings.Count > 0) {
    Console.WriteLine($"Total warnings: {warnings.Count}");
    foreach (var w in warnings) {
        Console.WriteLine($"  [{w.project}] {w.file}({w.line}): warning {w.code}: {w.msg}");
    }
}
EOF

